-- Biblioteka e madhe e përrallave, pjesa 5 nga 5 (22 përralla).
-- Përralla më të gjata (8–15 minuta lexim): popullore shqiptare, klasike të rrëfyera (Grim, Andersen, Ezopi, Peroi,
-- Kipling, Kolodi, Kerolli, Baumi e të tjera, të gjitha të lira nga e drejta e autorit) dhe përralla origjinale të Bebix-it.
-- Secila ka ilustrimin e vet (cover_svg, i kontrolluar me pastruesin e app-it) dhe dalin në app pa përditësim.
-- I sigurt për t'u ekzekutuar dy herë: përrallat që ekzistojnë (sipas slug) nuk preken. Nuk fshin asgjë.
-- Kërkon migrimet 20261024090000_stories.sql dhe 20261025090000_story_drafts.sql (kolona cover_svg, source).

insert into public.stories (slug, language, title, summary, paragraphs, categories, age_min_months, age_max_months, reading_minutes, cover_key, cover_svg, status, featured, sort_order, source)
values
(
  $s$lepuri-dhe-iriqi$s$, 'sq', $s$Lepuri dhe iriqi$s$,
  $s$Sipas vëllezërve Grim: një lepur mendjemadh tallet me këmbët e shkurtra të iriqit. Iriqi e sfidon në garë, dhe ka një plan që i duhet edhe gruaja e tij.$s$,
  array[
    $s$Ishte një mëngjes i bukur vere, një e diel. Dielli shkëlqente në qiell, era e lehtë lëkundte grurin, bletët zukatnin mes luleve dhe njerëzit, me rrobat e festës, shkonin në fshat. Iriqi, i kënaqur, kishte dalë para shtëpisë së tij, me duart në xhep, duke fishkëllyer një këngë.$s$,
    $s$«Do të shkoj të shikoj si po rriten rrepat», tha me vete. Rrepat ishin në arën e fermerit, pranë shtëpisë së iriqit, dhe iriqi i shikonte gjithmonë si të ishin të tijat. Mbylli derën dhe u nis. Kur arriti te ara, takoi lepurin, që kishte dalë për të njëjtin qëllim: të shikonte lakrat e tij.$s$,
    $s$Iriqi i tha me mirësjellje: «Mirëmëngjes!» Por lepuri, që ishte shumë mendjemadh, nuk iu përgjigj përshëndetjes. Vetëm e shikoi nga lart poshtë dhe tha: «Si ndodh që të shoh kaq herët në mëngjes duke u endur nëpër ara?» «Po shëtis», tha iriqi. «Po shëtit?» qeshi lepuri. «Me ato këmbë të shkurtra e të shtrembra? Mendoj se këmbët e tua mund të përdoren për diçka më të mirë.»$s$,
    $s$Iriqi u fye shumë. Mund të duronte çdo gjë, por jo që t'i qeshnin këmbët, sepse ishin të shkurtra e të shtrembra nga natyra. «Ti mendon», i tha lepurit, «se me këmbët e tua mund të bësh më shumë se unë me të miat?» «Sigurisht që po», tha lepuri. «Atëherë le të provojmë», tha iriqi. «Vë bast që, po të bëjmë garë, të mund unë.»$s$,
    $s$Lepuri qeshi aq shumë, sa iu dridhën veshët. «Ti, me këmbët e tua të shtrembra? Mirë, nëse do. Për çfarë vëmë bast?» «Për një monedhë ari dhe një shishe me lëng mollësh», tha iriqi. «Pranoj», tha lepuri. «Le ta fillojmë menjëherë.» «Jo, jo», tha iriqi. «Kam ende uri. Do të shkoj në shtëpi të ha mëngjes. Pas gjysmë ore, do të jem këtu.»$s$,
    $s$Rrugës për në shtëpi, iriqi mendoi: «Lepuri ka këmbë të gjata, por unë kam një plan.» Kur arriti, i tha gruas: «Grua, vish rrobat shpejt. Duhet të vish me mua në arë.» «Çfarë ka ndodhur?» pyeti gruaja. «Kam vënë bast me lepurin për një monedhë ari e për një shishe me lëng mollësh. Dhe ti do të më ndihmosh.»$s$,
    $s$Gjatë rrugës, iriqi i shpjegoi gruas planin. «Shiko atë arën e gjatë. Lepuri do të vrapojë në njërën brazdë, dhe unë në tjetrën. Do të fillojmë nga atje lart. Ti do të rrish këtu poshtë, në fund të brazdës sime. Kur lepuri të arrijë këtu, ti do të ngrihesh dhe do t'i thuash: Unë jam këtu tashmë!» Gruaja e iriqit qeshi. Ishte iriqe, dhe nga larg dukej krejt si i shoqi.$s$,
    $s$Iriqi e la gruan në fund të arës dhe u ngjit deri në krye, ku e priste lepuri. «Mund të fillojmë?» pyeti lepuri. «Po», tha iriqi. «Atëherë, një, dy, tre!» Dhe secili u vu në brazdën e vet. Lepuri u nis si era nëpër arë. Por iriqi bëri vetëm tre hapa, pastaj u ul në fund të brazdës dhe qëndroi aty, i qetë.$s$,
    $s$Kur lepuri, me gjithë shpejtësinë, arriti në fund të arës, iriqja u ngrit nga brazda e saj dhe tha: «Unë jam këtu tashmë!» Lepuri u habit aq shumë, sa mbeti me gojë hapur. Ishte i sigurt që ky ishte iriqi, sepse iriqët i ngjajnë shumë njëri-tjetrit. «Diçka nuk shkon», tha. «Edhe një herë! Mbrapsht!»$s$,
    $s$Dhe lepuri u nis përsëri si era, mbrapsht, nëpër arë, me veshët që i fluturonin pas. Por gruaja e iriqit qëndroi aty ku ishte. Kur lepuri arriti në krye të arës, iriqi u ngrit nga brazda e tij dhe tha: «Unë jam këtu tashmë!» Lepuri u nxeh e u bë i kuq si karota. «Edhe një herë!» bërtiti. «Sa herë të duash», tha iriqi.$s$,
    $s$Kështu lepuri vrapoi shtatëdhjetë e tri herë, lart e poshtë, dhe çdo herë, iriqi ose gruaja e tij i thoshin: «Unë jam këtu tashmë!» Herën e shtatëdhjetë e katërt, lepuri u lodh aq shumë, sa u shtri në mes të arës dhe s'mundi të ngrihej më për një kohë të gjatë. Ishte rraskapitur e i turpëruar.$s$,
    $s$Iriqi mori monedhën e arit dhe shishen me lëng mollësh, thirri gruan nga fundi i arës dhe të dy u kthyen në shtëpi të lumtur. Lepuri, kur më në fund u ngrit, shkoi në shtëpi duke çaluar, dhe që nga ajo ditë nuk u tall më kurrë me këmbët e askujt.$s$,
    $s$Mësimi i kësaj historie është i dyfishtë. Së pari, askush, sado i madh e sado i shpejtë, s'duhet të tallet me dikë më të vogël, sepse mendja vlen më shumë se këmbët. Dhe së dyti, kur do të martohesh, merr dikë që të ngjan e që të kupton. Kështu, kur të nevojitet ndihmë, do ta kesh gjithmonë pranë.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 36, 96, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="glepuridheiriqi" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#glepuridheiriqi)"/><circle cx="121.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 83.4Q40 74.5 80 86.5T160 90.8V120H0Z" fill="#B5D39A"/><path d="M0 101.7Q40 90 80 98T160 101.4V120H0Z" fill="#93BE7B"/><circle cx="41.7" cy="109" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="147.6" cy="108.6" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="112.6" cy="112.6" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="23.5" cy="107.2" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="37.5" cy="108.2" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="122.9" cy="107.2" r="1.6" fill="#E7B04B" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M8 56Q6 38 22 32L26 26L30 32L34 25L38 32L42 26L45 33L49 29L50 36Q58 42 58 52L62 54L56 57Q44 60 8 56Z" fill="#3E5A38"/><path d="M8 56Q6 38 22 32L26 26L30 32L34 25L38 32L42 26L45 33" fill="#F4F7EA" opacity="0.15"/><circle cx="52" cy="46" r="1.4" fill="#F4F7EA"/><circle cx="61" cy="54" r="1.8" fill="#F4F7EA"/><path d="M18 57L18 60M40 58L40 60" fill="none" stroke="#3E5A38" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
