(
  $s$vemja-qe-u-be-flutur$s$, 'sq', $s$Vemja që s'donte të flinte$s$,
  $s$Vemja Viti ka frikë nga gjumi i gjatë brenda fshikëzës. Por kur vjen koha, mëson që ndonjëherë ndryshimet më të bukura ndodhin kur pushojmë.$s$,
  array[
    $s$Në një kopsht me lule, mbi një gjethe të madhe hithre, lindi një vemje e vogël jeshile. Quhej Viti. Ishte e vogël sa një fije bari dhe kishte vetëm një gjë në mendje: të hante. Hëngri gjethen ku kishte lindur. Pastaj hëngri gjethen tjetër. Pastaj gjethen tjetër. Hante nga mëngjesi deri në mbrëmje, dhe rritej, rritej, rritej.$s$,
    $s$Viti ishte një vemje e gëzuar. I pëlqente të ecte ngadalë mbi gjethe, duke e mbledhur trupin si një hark e duke e zgjatur përsëri. I pëlqente të rrinte në diell. Dhe i pëlqenin fluturat, që shihte çdo ditë mbi lule. Ishin aq të bukura, me krahë me ngjyra, që fluturonin lehtë nga një lule te tjetra. «Sa do të doja të fluturoja», mendonte Viti.$s$,
    $s$Një ditë, një flutur e madhe portokalli me pika të zeza u ul pranë Vitit, mbi një lule. «Përshëndetje, vemje e vogël», i tha. «Si je?» «Mirë», tha Viti. «Por do të doja të isha si ti. Të kisha krahë.» Flutura qeshi butë. «Ti do të kesh krahë», i tha. «Do të bëhesh si unë. Por më parë, do të duhet të flesh një gjumë të gjatë.»$s$,
    $s$«Një gjumë të gjatë?» pyeti Viti, e shqetësuar. «Sa i gjatë?» «Disa javë», tha flutura. «Do të mbështillesh në një fshikëz, si në një shtrat të ngushtë, dhe do të flesh. Dhe kur të zgjohesh, do të jesh flutur.» Viti u tremb. «Disa javë? Në errësirë? Pa ngrënë, pa lëvizur, pa parë diellin? Jo, jo. Unë s'dua të fle kaq gjatë. Kam frikë.»$s$,
    $s$Flutura e shikoi me dhembshuri. «Edhe unë kisha frikë», i tha. «Të gjitha vemjet kanë frikë. Por gjumi nuk është i frikshëm. Gjumi është koha kur trupi yt ndryshon, pa e kuptuar ti. Ti fle, dhe brenda teje ndodh një mrekulli.» Pastaj flutura hapi krahët dhe fluturoi tutje. Por Viti nuk u bind. «Nuk do të fle kurrë kaq gjatë», tha.$s$,
    $s$Ditët kaluan. Viti vazhdoi të hante e të rritej, gjithnjë e më shumë. Por pastaj, një mbrëmje, ndjeu diçka të çuditshme. Ishte e lodhur. Shumë e lodhur. Trupi i saj i dukej i rëndë dhe sytë i mbylleshin vetë. «Jo», tha Viti. «Nuk dua të fle. Do të rri zgjuar.» Dhe u përpoq të ecte, të hante, të shikonte yjet. Por gjumi vinte, gjithnjë e më i fortë.$s$,
    $s$Një mi i vogël kaloi pranë dhe e pa Vitin që luftonte me gjumin. «Pse s'flen?» e pyeti. «Sepse kam frikë», tha Viti. «Nëse fle, do të ndryshoj. Dhe s'e di çfarë do të bëhem.» Miu u ul pranë saj. «E di», tha. «Çdo natë që unë fle, zgjohem pak më i madh, pak më i zgjuar. Edhe fëmijët e njerëzve, kur flenë, rriten. Gjumi s'është humbje. Gjumi është dhuratë që i bëjmë vetes.»$s$,
    $s$Viti mendoi. Pastaj vështroi lart, ku një flutur e bardhë kalonte në dritën e hënës, e lehtë si një petal. Dhe ndjeu që ishte koha. Me fijet e holla që i dilnin nga trupi, u var nga dega e një peme, kokëposhtë. Pastaj, ngadalë, filloi të mbështillej. Lëkura e saj u bë e fortë e e gjelbër, si një guaskë e vogël. Dhe brenda saj, Viti mbylli sytë.$s$,
    $s$Brenda fshikëzës ishte e qetë, e ngrohtë e e errët. Viti flinte. Ditët kalonin jashtë: dielli ngrihej e perëndonte, shiu binte, era lëkundte degën. Por Viti s'ndjente asgjë. Flinte një gjumë të thellë e të ëmbël. Dhe brenda saj, ndërsa flinte, po ndodhte diçka e mrekullueshme. Trupi i saj po ndryshonte. Po i rriteshin këmbë të holla, antena të gjata, sy të mëdhenj. Dhe në shpinë, të palosur si letër, po i rriteshin dy krahë.$s$,
    $s$Kaluan dy javë. Pastaj, një mëngjes me diell, fshikëza filloi të lëvizte. U ça pak në majë. Pastaj pak më shumë. Dhe nga brenda doli Viti, ngadalë, me kujdes. Ishte e lodhur, e lagur, me krahët e palosur e të rrudhur. U kap pas fshikëzës së boshatisur dhe priti, në diell, që krahët t'i thaheshin.$s$,
    $s$Krahët u hapën ngadalë, si dy lule që çelin. Ishin të mëdhenj, të kaltër si qielli, me pika të verdha si yje e me një kufi të zi të hollë. Viti i shikoi i habitur. Pastaj i lëvizi pak. Pastaj pak më shumë. Dhe papritur, pa e ditur si, u ngrit nga dega, lart në ajër, lehtë, shumë lehtë, mbi kopsht, mbi lule.$s$,
    $s$«Po fluturoj!» thirri Viti. «Po fluturoj!» Fluturoi mbi gjethen e hithrës ku kishte lindur, mbi lulet që kishte parë nga poshtë, deri te flutura portokalli me pika të zeza, që po pushonte mbi një trëndafil. «Kishe të drejtë», i tha. «Gjumi nuk ishte i frikshëm.» Flutura portokalli buzëqeshi. «E di», tha. «Gjumi është vendi ku ndodhin mrekullitë.»$s$,
    $s$Sonte, kur të mbyllësh sytë, mendo për Vitin. Edhe ti, kur fle, po rritesh. Trupi yt pushon, mendja jote rregullon gjithçka që ke mësuar sot, dhe zemra jote mbush forcë për nesër. Nuk do të të dalin krahë, natyrisht. Por nesër në mëngjes, do të jesh pak më i madh, pak më i zgjuar, pak më i fortë. Si një flutur e vogël që zgjohet. Natën e mirë.$s$
  ]::text[],
  array['nature', 'emotions', 'sleep']::text[], 0, 72, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gvemjaqeubeflutur" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gvemjaqeubeflutur)"/><circle cx="26.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 84.3Q40 72.1 80 84.1T160 80.1V120H0Z" fill="#B5D39A"/><path d="M0 102.9Q40 94.8 80 102.8T160 98.5V120H0Z" fill="#93BE7B"/><circle cx="28.1" cy="110.4" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="139.4" cy="113.8" r="1.6" fill="#FFFFFF" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="22" cy="24" rx="14" ry="12" fill="#E58C5A" transform="rotate(-25 22 24)"/><ellipse cx="42" cy="24" rx="14" ry="12" fill="#E58C5A" transform="rotate(25 42 24)"/><ellipse cx="24" cy="42" rx="10" ry="8" fill="#E7B04B" transform="rotate(25 24 42)"/><ellipse cx="40" cy="42" rx="10" ry="8" fill="#E7B04B" transform="rotate(-25 40 42)"/><circle cx="20" cy="22" r="3" fill="#F4F7EA" opacity="0.6"/><circle cx="44" cy="22" r="3" fill="#F4F7EA" opacity="0.6"/><ellipse cx="32" cy="33" rx="2.4" ry="14" fill="#3E5A38"/><path d="M31 20Q28 10 24 8M33 20Q36 10 40 8" fill="none" stroke="#3E5A38" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 1090, 'editor'
),
(
  $s$guacka-e-ksamilit$s$, 'sq', $s$Guacka e Ksamilit$s$,
  $s$Luani gjen në plazhin e Ksamilit guackën më të bukur që ka parë, dhe një gaforre e vogël pa shtëpi i tregon se edhe gjërat më të bukura kanë një zot.$s$,
  array[
    $s$Në Ksamil, deti është aq i kaltër sa duket sikur dikush ka derdhur bojë në të. Ka ishuj të vegjël me pisha, rërë të bardhë dhe gurë të lëmuar nga valët. Luani dhe familja e tij vinin këtu çdo verë, dhe Luani kishte një lojë të preferuar: kërkonte guacka.$s$,
    $s$Kishte gjetur shumë: guacka të vogla rozë si thonjtë e kukullave, guacka me vija si zebra, guacka të thyera që kishin brenda ngjyrën e ylberit. I mblidhte në një kovë të verdhë dhe në mbrëmje i rendiste në ballkonin e hotelit, nga më e vogla te më e madhja.$s$,
    $s$Një mëngjes, shumë herët, kur plazhi ishte ende bosh dhe deti ishte i qetë si pasqyrë, Luani eci deri në fund të plazhit, pranë shkëmbinjve. Dhe atje, gjysmë e fshehur në rërë, pa diçka që shkëlqente. E nxori me kujdes. Ishte guacka më e bukur që kishte parë ndonjëherë.$s$,
    $s$Ishte e madhe sa grushti i tij, e përdredhur si shkallët e një kulle, me ngjyrë krem e me pika kafe. Brenda ishte e lëmuar dhe rozë, si brendësia e një luleje. Luani e afroi te veshi, siç i kishte mësuar babai, dhe dëgjoi: shhhhh, shhhhh. Ishte zhurma e detit, edhe pse deti ishte aty pranë dhe i qetë.$s$,
    $s$«Kjo do të jetë e imja përgjithmonë», tha Luani. «Do ta çoj në shtëpi dhe do ta vë mbi tryezën pranë krevatit. Çdo natë do ta dëgjoj detin.»$s$,
    $s$Ndërsa po kthehej drejt çadrës së familjes, Luani vuri re diçka që lëvizte në rërë, pranë këmbëve të tij. Ishte një gaforre e vogël, e çuditshme, me dy dorëza të kuqe e me sy si dy kokrra piperi në majë të dy shkopinjve. Por kishte diçka të çuditshme: pjesa e pasme e trupit të saj ishte e butë, e zbuluar, dhe gaforrja dukej e trembur.$s$,
    $s$Gaforrja u ndal përpara Luanit dhe ngriti sytë drejt guackës që mbante në dorë. Pastaj bëri dy hapa anash, një përpara, dhe ngriti dorëzat sikur kërkonte diçka. Luani u ul në gjunjë. «Çfarë ke?» e pyeti. «Pse më shikon kështu?»$s$,
    $s$Ishte gjyshja e Luanit, që kishte dalë për shëtitje të mëngjesit, ajo që iu përgjigj. U ul pranë tij në rërë dhe shikoi gaforren. «Kjo është një gaforre vetmitare», tha. «Nuk ka guackë të sajën. Gjen guackat e boshatisura në rërë dhe jeton brenda tyre. Kur rritet, guacka i bëhet e vogël dhe duhet të kërkojë një më të madhe. Kjo e gjorë ka lënë të vjetrën dhe po kërkon shtëpi të re.»$s$,
    $s$Luani shikoi guackën në dorë, pastaj gaforren. «Do të thuash që... kjo është shtëpia e saj?» «Mund të bëhet», tha gjyshja. «Por vendimin e merr ti. E ke gjetur ti.»$s$,
    $s$Luani e mbajti guackën edhe pak. E afroi edhe një herë te veshi. Shhhhh. Mendoi tryezën pranë krevatit, mendoi netët e dimrit kur do të donte të dëgjonte detin. Pastaj shikoi gaforren e vogël, që priste me sytë e saj si kokrra piperi, pa shtëpi, e zbuluar, në mes të plazhit të madh.$s$,
    $s$Me kujdes, Luani e vuri guackën në rërë, me gojën nga gaforrja. Gaforrja u afrua ngadalë. E preku guackën me dorëzat, e kontrolloi brenda, e rrotulloi pak. Pastaj, me një lëvizje të shpejtë, futi trupin e butë brenda saj, dhe pas një çasti, nxori kokën nga gryka, me sytë lart. Kishte shtëpi të re.$s$,
    $s$Gaforrja bëri disa hapa me shtëpinë e saj të re në shpinë, pak e lëkundur, si një fëmijë me çantë të madhe shkolle. Pastaj u kthye, sikur për ta përshëndetur Luanin, dhe u fut ngadalë në ujë, mes gurëve.$s$,
    $s$«A je mërzitur?» e pyeti gjyshja. Luani u mendua. «Pak», tha. «Por tani, kur ta dëgjoj detin, do të di që aty brenda jeton dikush.» Gjyshja e përqafoi. «Kjo është guacka më e bukur që ke gjetur», tha. «Sepse e dhurove.»$s$,
    $s$Atë mbrëmje, në ballkonin e hotelit, Luani i rendisi guackat e tjera. Kishte një vend bosh në fund të rreshtit, aty ku do të ishte guacka e madhe. E la bosh. Dhe kur ra nata, dëgjoi nga larg zhurmën e detit, shhhhh, shhhhh, dhe mendoi për gaforren e vogël që flinte në shtëpinë e saj të re, në fund të ujit të kaltër të Ksamilit.$s$
  ]::text[],
  array['nature', 'lessons']::text[], 0, 84, 9, 'boat',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gguackaeksamilit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C6E3EC"/><stop offset="1" stop-color="#EEF7F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gguackaeksamilit)"/><circle cx="120.9" cy="22" r="9" fill="#FFF3D6"/><path d="M37.9 34l4 3l4 -3M121 28l3 2.4l3 -2.4" fill="none" stroke="#5EA4B6" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><rect x="0" y="76" width="160" height="44" rx="0" fill="#8CC3CF"/><path d="M0 86Q10 82 20 86T40 86T60 86T80 86T100 86T120 86T140 86T160 86" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/><rect x="0" y="100" width="160" height="20" rx="0" fill="#5EA4B6"/><path d="M0 106Q10 102 20 106T40 106T60 106T80 106T100 106T120 106T140 106T160 106" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 56L6 34Q8 14 32 10Q56 14 58 34Z" fill="#2A5263"/><path d="M32 54L14 22M32 54L24 14M32 54L32 11M32 54L40 14M32 54L50 22" fill="none" stroke="#EEF7F8" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><rect x="26" y="52" width="12" height="6" rx="2" fill="#2A5263"/><path d="M0 60Q16 56 32 60T64 60" fill="none" stroke="#E39A55" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', false, 1100, 'editor'
),
(
  $s$ujku-dhe-shtate-kecat$s$, 'sq', $s$Ujku dhe shtatë kecat$s$,
  $s$Sipas vëllezërve Grim: mama dhi i paralajmëron shtatë kecat të mos ia hapin derën ujkut. Ujku provon çdo dredhi, por kecat dhe mama janë më të zgjuar.$s$,
  array[
    $s$Na ishte një herë një dhi e vjetër që kishte shtatë keca të vegjël, dhe i donte ashtu si një nënë i do fëmijët e saj. Një ditë, duhej të shkonte në pyll për të mbledhur ushqim. Thirri të shtatë kecat dhe u tha: «Të dashurit e mi, unë po shkoj në pyll. Ruhuni nga ujku! Nëse hyn, do t'ju hajë të gjithëve. Ujku shpesh maskohet, por do ta njihni nga zëri i trashë dhe nga këmbët e zeza.»$s$,
    $s$«Mos u shqetëso, mama», thanë kecat. «Do të kemi kujdes.» Dhia u përshëndet dhe iku e qetë. Pas pak kohe, dikush trokiti në derë dhe thirri: «Hapni, fëmijë të dashur. Jam nëna juaj dhe ju kam sjellë diçka për secilin.» Por kecat e njohën nga zëri i trashë. «Nuk të hapim», thirrën. «Ti s'je nëna jonë. Ajo ka zë të ëmbël e të butë. Ti ke zë të trashë. Ti je ujku!»$s$,
    $s$Ujku shkoi te tregtari dhe bleu një copë të madhe shkumës. E hëngri, dhe zëri iu bë më i hollë. Pastaj u kthye, trokiti në derë dhe thirri me zë të butë: «Hapni, fëmijë të dashur. Jam nëna juaj.» Por ujku kishte vënë putrën e zezë në dritare, dhe kecat e panë. «Nuk të hapim. Nëna jonë s'ka këmbë të zeza si ti. Ti je ujku!»$s$,
    $s$Ujku vrapoi te furrtari. «Kam lënduar këmbën», i tha. «Ma lyej me brumë.» Pastaj vrapoi te mullixhiu. «Ma spërkat këmbën me miell të bardhë.» Mullixhiu mendoi: «Ky ujk do të mashtrojë dikë», dhe nuk donte. Por ujku i bërtiti aq shumë, sa mullixhiu u tremb dhe ia bëri këmbën të bardhë. Kështu janë njerëzit, ndonjëherë.$s$,
    $s$Për herë të tretë, ujku shkoi te dera, trokiti dhe tha: «Hapni, fëmijë të dashur. Jam nëna juaj, dhe ju kam sjellë diçka të mirë nga pylli.» Kecat thirrën: «Na trego këmbën më parë, që ta dimë nëse je nëna jonë.» Ujku vuri putrën e bardhë në dritare. Kecat panë që ishte e bardhë, dhe zëri ishte i hollë, dhe besuan. Hapën derën.$s$,
    $s$Por ishte ujku! Kecat u trembën e vrapuan të fshiheshin. I pari u fut nën tryezë, i dyti në shtrat, i treti në furrën e ftohtë, i katërti në kuzhinë, i pesti në dollap, i gjashti nën lavaman, dhe i shtati, më i vogli, në kutinë e orës së madhe të murit. Ujku i kërkoi një nga një. Por kecat ishin të shpejtë: kur ujku hapte një derë, keci kërcente nga dritarja; kur ujku shikonte nën tryezë, keci rrëshqiste nën shtrat.$s$,
    $s$Ujku vraponte rreth e qark shtëpisë, duke përplasur karriget e duke rrëzuar tasat, por s'kapi dot asnjë. Kecat kërcenin, iknin, fshiheshin, dhe çdo herë që ujku mendonte se e kishte zënë njërin, ai i shpëtonte përsëri. Më në fund, ujku u lodh aq shumë, sa u shtri në livadh nën një pemë jashtë shtëpisë dhe ra në gjumë, duke gërhitur aq fort, sa dridheshin degët.$s$,
    $s$Pak më vonë, dhia u kthye nga pylli. Ah, çfarë pa! Dera e shtëpisë ishte e hapur, tryeza, karriget e stolat ishin përmbys, tasi i larjes ishte thyer, jorganët dhe jastëkët ishin hedhur nga shtrati. Kërkoi kecat, por s'i gjeti dot. I thirri me emër, njërin pas tjetrit, por askush s'u përgjigj. Më në fund, kur thirri më të voglin, një zë i hollë i tha: «Mama e dashur, jam këtu, në kutinë e orës.»$s$,
    $s$Dhia e nxori kecin e vogël, dhe ai i tregoi gjithçka. «Dhe të tjerët?» pyeti dhia, me zemrën që i rrihte fort. «Ikën, mama», tha keci. «U fshehën ku mundën.» Dhia doli në oborr dhe filloi të thërriste, butë: «Fëmijë, ujku fle. Dilni, se jam unë, nëna juaj.» Dhe një nga një, nga stalla, nga koteci, nga pas gardhit, nga hambari, nga shkurret dhe nga pema e mollës, dolën gjashtë kecat e tjerë, të trembur, por shëndoshë e mirë.$s$,
    $s$U përqafuan të gjithë, me lot gëzimi. Pastaj nëna pa ujkun që flinte nën pemë, me barkun bosh e me gojën hapur. «Do t'i japim një mësim që s'do ta harrojë», tha. Kecat sollën gurë të mëdhenj nga përroi dhe i vendosën rreth ujkut, në formë rrethi. Pastaj mbushën një kovë të madhe me ujë të ftohtë nga pusi, sa më të ftohtë.$s$,
    $s$«Një, dy, tre!» tha dhia, dhe e hodhën kovën me ujë të ftohtë mbi ujkun. Ujku u hodh përpjetë me një ulërimë, u përplas te gurët, ra në pellgun e baltës dhe, kur pa dhinë me brirët e ngritur e shtatë kecat që i bërtisnin, u tremb aq shumë sa iku me vrap nëpër pyll, i lagur e me baltë deri në veshë. Dhe s'u kthye më kurrë në atë anë të pyllit.$s$,
    $s$Kecat kërcyen e vallëzuan rreth pusit, duke kënduar: «Ujku iku! Ujku iku!» Dhe nëna e tyre vallëzoi me ta. Pastaj u futën të gjithë në shtëpi, rregulluan tryezën, karriget e jastëkët, dhe hëngrën darkë bashkë. Dhe atë natë, para gjumit, nëna u tha: «Sot mësuat diçka. Kur dikush ju thotë se është dikush tjetër, kontrolloni mirë. Dhe kur keni frikë, fshihuni e kërkoni ndihmë.» Dhe shtatë kecat fjetën të gjithë bashkë, të ngrohtë, pranë nënës.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 36, 96, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gujkudheshtatekecat" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gujkudheshtatekecat)"/><path d="M11.6 45.8L21.6 100H1.6Z" fill="#5F8C76" opacity="0.85"/><path d="M21.1 46.6L31.1 100H11.1Z" fill="#8FB5A0" opacity="0.85"/><path d="M37.7 47.8L47.7 100H27.7Z" fill="#5F8C76" opacity="0.85"/><path d="M45.1 51.2L55.1 100H35.1Z" fill="#8FB5A0" opacity="0.85"/><path d="M116.5 42.3L126.5 100H106.5Z" fill="#5F8C76" opacity="0.85"/><path d="M128.1 52.3L138.1 100H118.1Z" fill="#8FB5A0" opacity="0.85"/><path d="M143.5 46.1L153.5 100H133.5Z" fill="#5F8C76" opacity="0.85"/><path d="M0 102.2Q40 96.1 80 102.1T160 102.9V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="28" cy="38" rx="18" ry="11" fill="#2C463B"/><path d="M40 34L48 22L56 26L50 36Z" fill="#2C463B"/><ellipse cx="53" cy="25" rx="6" ry="5" fill="#2C463B" transform="rotate(20 53 25)"/><path d="M50 20Q54 10 46 8" fill="none" stroke="#D9644A" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><path d="M55 29L57 38L52 32Z" fill="#2C463B"/><circle cx="52" cy="23" r="1.1" fill="#EDF3EC"/><path d="M14 46L13 60M20 47L20 60M36 47L36 60M42 46L43 60" fill="none" stroke="#2C463B" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M10 34L4 30L9 38Z" fill="#2C463B"/></g></svg>$s$,
  'published', false, 1110, 'editor'
),
(
  $s$kafshet-pergatiten-per-dimer$s$, 'sq', $s$Si përgatiten kafshët për dimër$s$,
  $s$Dimri po vjen në pyll. Ariu ha shumë, ketri fsheh arra, dallëndyshja niset drejt jugut, iriqi bën shtratin. Dhe vogëlushja Nora mëson si përgatitet edhe familja e saj.$s$,
  array[
    $s$Ishte fund tetori, dhe pylli pranë shtëpisë së Norës kishte ndryshuar ngjyrë. Gjethet e ahut ishin bërë të verdha, të lisave kafe, të panjave të kuqe si zjarri. Ajri i mëngjesit ishte i freskët dhe kishte erë dheu të lagur. «Dimri po vjen», tha gjyshi, ndërsa po ecnin në shteg. «Shiko si përgatiten kafshët.»$s$,
    $s$E para që panë ishte një ketër i kuq, që vraponte poshtë një lisi me faqet e fryra. «Çfarë po bën?» pyeti Nora. «Po fsheh arra e lende», tha gjyshi. «Gjatë vjeshtës, ketri mbledh qindra fara dhe i fsheh në vende të ndryshme: në tokë, në zgavra, nën gurë. Në dimër, kur s'ka ushqim, i gjen me hundën e tij.» «Po sikur të harrojë ku i ka fshehur?» «Ndonjëherë harron», qeshi gjyshi. «Dhe nga lendet e harruara, në pranverë, mbijnë lisa të rinj.»$s$,
    $s$Më tej, në një degë, panë dallëndyshet. Ishin dhjetëra, të rreshtuara mbi një tel, që cicëronin me zë të lartë. «Po bisedojnë», tha gjyshi. «Po bëjnë planin e udhëtimit. Së shpejti do të nisen drejt Afrikës, ku dimri është i ngrohtë dhe ka shumë mushkonja për të ngrënë. Do të fluturojnë mijëra kilometra, mbi det e shkretëtirë. Dhe në pranverë, do të kthehen këtu, në të njëjtat fole.»$s$,
    $s$Pranë përroit, panë gjurmë të mëdha në baltë. «Këto janë gjurmë ariu», tha gjyshi me zë të ulët. «Ariu, në vjeshtë, ha shumë. Ha kokrra, rrënjë, mjaltë, lende, sa mundet. Bëhet i trashë e i rëndë. Sepse në dimër, do të futet në një shpellë dhe do të flejë për muaj të tërë, pa ngrënë. Do të jetojë me dhjamin që ka mbledhur.» «Si ne kur hamë shumë në festa?» pyeti Nora. Gjyshi qeshi. «Pak a shumë.»$s$,
    $s$Pak më tej, nën një grumbull gjethesh të thata, Nora pa diçka që lëvizte. Ishte një iriq i vogël, që po mblidhte gjethe me hundë dhe i çonte nën një shkurre. «Po bën shtratin», tha gjyshi. «Do të mbështillet aty brenda, në një top të vogël, dhe do të flejë gjithë dimrin. Zemra e tij do të rrahë shumë ngadalë, dhe trupi i tij do të ftohet. Dhe do të zgjohet në mars, kur dielli të ngrohë përsëri.»$s$,
    $s$Në pellgun e pyllit, uji ishte i qetë e i errët. «Ku janë bretkosat?» pyeti Nora, që në verë i kishte dëgjuar të këndonin. «Kanë shkuar nën baltë, në fund të pellgut», tha gjyshi. «Do të flenë aty, në ujë të ftohtë, gjithë dimrin. Edhe peshqit do të shkojnë në fund, ku uji s'ngrin kurrë.»$s$,
    $s$Pastaj panë një dhelpër, që kaloi shpejt mes pemëve. Qimet e saj ishin bërë më të trasha e më të dendura. «Dhelpra nuk fle në dimër», tha gjyshi. «Por i rritet një pallto e re, më e ngrohtë. Edhe drerët, edhe ujqit. Dhe lepuri i malit, lart në Alpe, ndryshon edhe ngjyrë: nga kafe bëhet krejt i bardhë, që të mos duket në borë.»$s$,
    $s$Nora u mendua. «Gjysh», tha, «po bletët? Ku shkojnë bletët në dimër?» «Bletët rrinë në koshere», tha gjyshi, «të gjitha bashkë, rreth mbretëreshës. Ngrohen duke dridhur krahët, dhe hanë mjaltin që kanë mbledhur gjithë verën. Kjo është arsyeja pse bletët punojnë kaq shumë në verë. Ruajnë ushqim për dimrin.»$s$,
    $s$Kur u kthyen në shtëpi, Nora pa që edhe familja e saj po përgatitej për dimër. Babai po priste dru në oborr dhe i rendiste në grumbuj pranë murit. Mamaja po bënte reçel me fiq dhe turshi me lakër, që i rendiste në kavanoza në qilar. Gjyshja po thurte çorape leshi dhe një shall të ri për Norën, të kuq e të gjatë.$s$,
    $s$«E sheh?» tha gjyshi. «Edhe ne jemi si ketri. Mbledhim ushqim. Jemi si ariu, që përgatit strofullën. Jemi si bletët, që rrinë bashkë e ngrohen. Dimri është i gjatë, dhe kush përgatitet mirë, e kalon mirë.»$s$,
    $s$Atë mbrëmje, ra shiu i parë i ftohtë i vjeshtës. Nora u ul pranë sobës, me çorapet e reja të gjyshes, me një filxhan çaj me mjaltë. Dhe mendoi për kafshët e pyllit. Për ketrin në zgavrën e tij me arra. Për iriqin në shtratin me gjethe. Për ariun që po kërkonte shpellën. Për dallëndyshet që fluturonin drejt jugut, në errësirë, mbi det.$s$,
    $s$«Natën e mirë, kafshë të pyllit», pëshpëriti Nora, para se ta zinte gjumi. «Kaloni një dimër të ngrohtë. Dhe shihemi në pranverë.» Jashtë, shiu binte butë mbi gjethet. Dhe në pyll, kafshët, secila në mënyrën e saj, po bëheshin gati për një gjumë të gjatë. Edhe ti, sonte, bëhu gati. Gjumi po vjen.$s$
  ]::text[],
  array['nature']::text[], 0, 84, 10, 'seed',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkafshetpergatitenper" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkafshetpergatitenper)"/><path d="M7.6 58.3L17.6 100H-2.4Z" fill="#5F8C76" opacity="0.85"/><path d="M20.7 53.3L30.7 100H10.7Z" fill="#8FB5A0" opacity="0.85"/><circle cx="34.9" cy="74.6" r="16.9" fill="#8FB5A0" opacity="0.85"/><circle cx="48.1" cy="75.3" r="16.5" fill="#8FB5A0" opacity="0.85"/><circle cx="113.8" cy="68.4" r="21.1" fill="#8FB5A0" opacity="0.85"/><circle cx="130.3" cy="71" r="19.3" fill="#8FB5A0" opacity="0.85"/><path d="M146.9 43.6L156.9 100H136.9Z" fill="#5F8C76" opacity="0.85"/><path d="M0 102.6Q40 96.3 80 102.3T160 100.6V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 4L38 18L52 12L46 28L60 32L46 38L50 50L36 44L32 58L28 44L14 50L18 38L4 32L18 28L12 12L26 18Z" fill="#D9644A"/><path d="M32 58V20M32 34L44 26M32 34L20 26" fill="none" stroke="#EDF3EC" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/></g></svg>$s$,
  'published', false, 1120, 'editor'
),
(
  $s$dhurata-e-kroit$s$, 'sq', $s$Dhurata e kroit$s$,
  $s$Sipas Sharl Peroit: një vajzë e mirë i jep ujë një plake te kroi, dhe çdo fjalë që thotë pas kësaj i bëhet lule. E motra, që shkon me mendjemadhësi, merr një dhuratë krejt tjetër.$s$,
  array[
    $s$Na ishte një herë një grua e ve që kishte dy vajza. E madhja i ngjante nënës: ishte krenare, e ftohtë dhe s'i pëlqente të punonte. E vogla i ngjante babait të saj të ndjerë: ishte e butë, e sjellshme dhe me zemër të mirë. Por nëna e donte vetëm të madhen, sepse i ngjante, dhe të voglën e linte të bënte të gjitha punët e shtëpisë.$s$,
    $s$Midis punëve, vajza e vogël duhej të shkonte dy herë në ditë te një krua, larg në pyll, të mbushte një shtambë të madhe me ujë. Rruga ishte e gjatë, shtamba ishte e rëndë, dhe vajza kthehej gjithmonë e lodhur. Por nuk ankohej. Gjatë rrugës, këndonte me zogjtë dhe u fliste pemëve.$s$,
    $s$Një ditë, ndërsa po mbushte shtambën, iu afrua një plakë e varfër, e lodhur nga rruga. «Bija ime», i tha, «a më jep pak ujë të pi? Kam ecur shumë dhe kam etje.» «Me gjithë qejf, nëne», tha vajza. E shpëlau shtambën, e mbushi me ujë nga vendi më i pastër i kroit dhe ia afroi plakës, duke e mbajtur me të dyja duart që ajo të pinte lehtë.$s$,
    $s$Kur plaka piu, i tha: «Je kaq e mirë, kaq e sjellshme, sa dua të të jap një dhuratë.» Sepse ajo plakë ishte në të vërtetë një zanë, që kishte marrë pamjen e një plake të varfër për të parë sa e mirë ishte vajza. «Dhurata ime është kjo: sa herë që të flasësh, nga goja jote do të dalin lule dhe perla.»$s$,
    $s$Kur vajza u kthye në shtëpi, nëna e qortoi që ishte vonuar. «Më falni, nënë», tha vajza, «që u vonova.» Dhe ndërsa fliste, nga goja i dolën dy trëndafila, dy perla dhe dy diamante. Nëna u habit. «Çfarë sheh syri im? Si ndodhi kjo, bija ime?» Ishte hera e parë që e thërriste bija ime.$s$,
    $s$Vajza i tregoi me ndershmëri gjithçka që kishte ndodhur, dhe ndërsa fliste, lulet e perlat binin në dysheme si shi. Nëna mendoi menjëherë: «Duhet ta dërgoj edhe vajzën time të madhe. Do të bëhet e pasur!» Thirri të madhen. «Merr shtambën dhe shko te kroi. Kur të të kërkojë ujë një plakë e varfër, jepi me mirësjellje.»$s$,
    $s$«Ç'thua?» tha e madhja. «Unë të shkoj te kroi? S'kam ndër mend!» «Do të shkosh», tha nëna, «dhe menjëherë.» E madhja shkoi, duke murmuritur, por mori me vete shtambën më të bukur prej argjendi që kishin në shtëpi. Kur arriti te kroi, doli nga pylli një zonjë e veshur shumë bukur, me rroba mëndafshi, që i kërkoi ujë. Ishte e njëjta zanë, por kësaj radhe kishte marrë pamjen e një princeshe.$s$,
    $s$«Mos vallë kam ardhur këtu për t'ju shërbyer juve?» tha e madhja me krenari. «Mos mendoni se e solla këtë shtambë argjendi për t'ju dhënë ujë? Po pati etje, pini vetë nga kroi.» Zana e shikoi me qetësi. «Nuk je shumë e sjellshme», i tha. «Atëherë, meqë je kaq e pasjellshme, ja dhurata ime: sa herë që të flasësh, nga goja jote do të dalin bretkosa dhe hardhuca.»$s$,
    $s$Kur e madhja u kthye në shtëpi, nëna i doli përpara. «Pra, bija ime?» «Pra, nënë?» u përgjigj ajo, dhe nga goja i kërcyen dy bretkosa dhe dy hardhuca. «O Zot!» thirri nëna. «Çfarë ka ndodhur? Kjo është faji i motrës sate!» Dhe u zemërua me vajzën e vogël, sikur të ishte ajo fajtorja.$s$,
    $s$Vajza e vogël, e trishtuar, iku në pyll dhe u fsheh te kroi. Aty e gjeti një princ i ri, që po kthehej nga gjuetia. E pa të qante dhe e pyeti pse. Ndërsa ajo i tregonte, lulet dhe perlat binin rreth saj, dhe princi kuptoi që kjo ishte një dhuratë që vinte nga zemra e saj e mirë. Por ajo që i bëri më shumë përshtypje princit, nuk ishin perlat, por mënyra se si ajo fliste për motrën e saj: pa zemërim, me keqardhje, duke shpresuar që ajo të ndryshonte.$s$,
    $s$Princi e çoi në pallatin e babait të tij, dhe pas pak kohësh u martuan. Dhe vajza e vogël nuk e harroi motrën. Shkoi ta takonte dhe i tha: «Zana s'të ka dënuar përgjithmonë. Bretkosat dhe hardhucat dalin vetëm nga fjalët e ashpra. Provo të thuash diçka të mirë.»$s$,
    $s$E madhja u mendua gjatë. Pastaj, me shumë vështirësi, si dikush që mëson një gjuhë të re, tha: «Faleminderit.» Dhe nga goja e saj nuk doli asnjë bretkosë. Doli një lule e vogël e bardhë, një margaritë. E madhja qau. Dhe filloi të mësonte, ditë pas dite, të fliste me mirësi. Bretkosat u pakësuan, margaritat u shtuan. Thonë se pas disa vitesh, edhe nga goja e saj dilnin trëndafila.$s$,
    $s$Fjalët e mira, o fëmija im, janë si lulet. Fjalët e ashpra janë si bretkosat. Dhe secili prej nesh mund të zgjedhë çdo ditë, çfarë do të dalë nga goja e tij.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 48, 120, 10, 'seed',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gdhurataekroit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gdhurataekroit)"/><circle cx="10.3" cy="73.7" r="17.5" fill="#8FB5A0" opacity="0.85"/><circle cx="20.9" cy="71.8" r="18.8" fill="#8FB5A0" opacity="0.85"/><path d="M32.1 56.8L42.1 100H22.1Z" fill="#5F8C76" opacity="0.85"/><circle cx="46.2" cy="79.7" r="13.5" fill="#8FB5A0" opacity="0.85"/><path d="M115.4 47.5L125.4 100H105.4Z" fill="#5F8C76" opacity="0.85"/><circle cx="128.9" cy="75.2" r="16.5" fill="#8FB5A0" opacity="0.85"/><path d="M146.2 42L156.2 100H136.2Z" fill="#5F8C76" opacity="0.85"/><path d="M0 100.2Q40 95.6 80 101.6T160 99.3V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 60V28" fill="none" stroke="#7DA86B" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="24" cy="46" rx="8" ry="3.5" fill="#7DA86B" transform="rotate(-30 24 46)"/><ellipse cx="40" cy="40" rx="8" ry="3.5" fill="#7DA86B" transform="rotate(30 40 40)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#D9644A"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#D9644A" transform="rotate(72 32 24)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#D9644A" transform="rotate(144 32 24)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#D9644A" transform="rotate(216 32 24)"/><ellipse cx="32" cy="14" rx="6" ry="9" fill="#D9644A" transform="rotate(288 32 24)"/><circle cx="32" cy="24" r="5" fill="#E7B04B"/></g></svg>$s$,
