(
  $s$shahu-dhe-kokrrat-e-orizit$s$, 'sq', $s$Shahu dhe kokrrat e orizit$s$,
  $s$Legjendë e vjetër indiane: një mësues i urtë shpik lojën e shahut për një mbret të mërzitur, dhe si shpërblim kërkon vetëm disa kokrra oriz mbi fushat e tabelës. Mbreti qesh, derisa fillon të numërojë.$s$,
  array[
    $s$Shumë kohë më parë, në Indi, jetonte një mbret i pasur, që kishte pallate, kopshte e elefantë, por që mërzitej shumë. Kishte provuar çdo lojë që njihej në mbretërinë e tij, dhe të gjitha i dukeshin të lehta. Një ditë shpalli: «Kush më sjell një lojë që të mos më mërzitë kurrë, do të marrë çfarë të kërkojë.»$s$,
    $s$Në një fshat të largët jetonte një mësues i vjetër që quhej Sesa. U mësonte fëmijëve të fshatit shkrim e numra, nën hijen e një peme të madhe. Kur dëgjoi shpalljen, Sesa nuk mendoi për shpërblimin. Mendoi për mbretin, që kishte gjithçka, por s'kishte mësuar kurrë të mendonte me durim. Dhe gjithë dimrin, në mbrëmje, pranë llambës, gdhendi diçka me thikën e tij të vogël.$s$,
    $s$Në pranverë, Sesa shkoi në pallat me një tabelë druri, të ndarë në tetë rreshta me nga tetë katrorë, gjithsej gjashtëdhjetë e katër, njëri i bardhë e tjetri i zi. Mbi tabelë vendosi figura të vogla: ushtarë, kalorës, elefantë, kala, një mbret dhe një mbretëreshë. «Kjo lojë quhet shah», tha. «Çdo figurë lëviz ndryshe. Dhe fiton jo ai që ka ushtrinë më të madhe, por ai që mendon më mirë.»$s$,
    $s$Mbreti luajti me Sesën gjithë ditën. Humbi një herë, dy herë, dhjetë herë. Mësoi se ushtari i vogël, po të ecte me durim deri në fund të tabelës, mund të bëhej mbretëreshë. Mësoi se mbreti, figura më e rëndësishme, ishte edhe më e dobëta, dhe s'mund të mbijetonte pa të tjerët. Dhe për herë të parë pas shumë vitesh, mbreti nuk u mërzit.$s$,
    $s$«Më ke dhënë lojën më të bukur në botë», tha mbreti. «Kërko çfarë të duash. Ar, pallate, toka.» Sesa u përkul. «Madhëri, unë jam njeri i thjeshtë. Më jepni vetëm pak oriz. Vini një kokërr oriz në katrorin e parë të tabelës. Dy kokrra në të dytin. Katër në të tretin. Tetë në të katërtin. Dhe kështu me radhë, çdo katror dyfishin e të mëparshmit, deri në katrorin e gjashtëdhjetë e katërt.»$s$,
    $s$Mbreti qeshi me të madhe, dhe me të qeshi gjithë oborri. «Vetëm kaq? Disa kokrra oriz? Më ofendon me një dëshirë kaq të vogël!» Por Sesa nuk ndryshoi mendje. «Mjaft të jetë ashtu siç e kërkova», tha. Mbreti tundi dorën dhe urdhëroi llogaritarët e tij t'i jepnin mësuesit orizin, dhe u kthye te tabela e shahut.$s$,
    $s$Llogaritarët filluan të numëronin. Në katrorin e dhjetë, kishte pesëqind e dymbëdhjetë kokrra: sa një grusht i vogël. Në katrorin e njëzetë, mbi gjysmë milioni: disa thasë të mëdhenj. Në katrorin e tridhjetë, mbi pesëqind milionë kokrra: sa gjithë orizi i një fshati të madh për një vit. Llogaritarët u zbehën, dhe vazhduan të numëronin gjithë natën.$s$,
    $s$Në mëngjes, kryellogaritari erdhi te mbreti me duar që i dridheshin. «Madhëri», tha, «na falni. Në katrorin e gjashtëdhjetë e katërt, do të duheshin më shumë kokrra oriz sesa ka në gjithë mbretërinë tonë. Më shumë sesa ka në gjithë botën. Edhe sikur të mbillnim oriz në çdo fushë të tokës për një mijë vjet, s'do të mjaftonte.»$s$,
    $s$Mbreti mbeti pa fjalë. Pastaj thirri Sesën. «Më mashtrove», tha, por pa zemërim, sepse ishte më shumë i habitur. «Jo, madhëri», tha Sesa. «Ju dhashë një mësim të dytë, bashkë me lojën. Diçka e vogël, që rritet pak nga pak, me durim, mund të bëhet më e madhe se gjithçka. Dhe një mbret duhet ta mendojë mirë para se të premtojë.»$s$,
    $s$Mbreti u mendua gjatë. «Atëherë më thuaj», tha, «çfarë të jap, që të mbaj fjalën time sa mundem?» Sesa buzëqeshi. «Hapni hambarët tuaj për fshatrat e varfra, madhëri. Për çdo katror të tabelës, një fshat që s'do të ketë më uri. Gjashtëdhjetë e katër fshatra. Kaq më mjafton mua.»$s$,
    $s$Dhe kështu u bë. Hambarët e mbretit u hapën, dhe gjashtëdhjetë e katër fshatra morën oriz për gjithë vitin. Fëmijët e tyre hëngrën, u rritën dhe shkuan në shkollë. Mbreti mbajti Sesën në pallat si këshilltar, dhe çdo mbrëmje luanin shah bashkë. Mbreti nuk fitoi shpesh, por mësoi shumë.$s$,
    $s$Shahu udhëtoi nga India në Persi, nga Persia te arabët, nga arabët në Evropë, dhe sot luhet në gjithë botën, edhe në Shqipëri. Dhe kur ta shohësh një tabelë shahu, me gjashtëdhjetë e katër katrorët e saj, kujto mësuesin Sesa dhe kokrrat e tij të orizit. Dhe mbaje mend: një kokërr e vogël, një hap i vogël, një fjalë e mirë çdo ditë, me durim, mund të bëhen diçka shumë e madhe.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 60, 144, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gshahudhekokrrateoriz" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gshahudhekokrrateoriz)"/><rect x="14" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M24 23Q24 26 27 26Q24 26 24 29Q24 26 21 26Q24 26 24 23Z" fill="#F3EBD9"/><circle cx="38" cy="24" r="5" fill="#F3EBD9"/><path d="M31 14V54M14 34H48" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="124" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="127" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><rect x="0" y="54" width="8" height="6" rx="0" fill="#7A4E3A" opacity="0.6"/><rect x="8" y="54" width="8" height="6" rx="0" fill="#F8EEE3" opacity="0.6"/><rect x="16" y="54" width="8" height="6" rx="0" fill="#7A4E3A" opacity="0.6"/><rect x="24" y="54" width="8" height="6" rx="0" fill="#F8EEE3" opacity="0.6"/><rect x="32" y="54" width="8" height="6" rx="0" fill="#7A4E3A" opacity="0.6"/><rect x="40" y="54" width="8" height="6" rx="0" fill="#F8EEE3" opacity="0.6"/><rect x="48" y="54" width="8" height="6" rx="0" fill="#7A4E3A" opacity="0.6"/><rect x="56" y="54" width="8" height="6" rx="0" fill="#F8EEE3" opacity="0.6"/><path d="M14 52H30L28 46H16Z" fill="#7A4E3A"/><path d="M18 46Q14 30 22 22Q30 30 26 46Z" fill="#7A4E3A"/><circle cx="22" cy="18" r="4" fill="#7A4E3A"/><path d="M36 52H54L52 46H38Z" fill="#7A4E3A"/><path d="M40 46L42 20H48L50 46Z" fill="#7A4E3A"/><path d="M40 20L39 12H51L50 20Z" fill="#7A4E3A"/><path d="M45 12V4M42 7H48" fill="none" stroke="#7A4E3A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 1190, 'editor'
),
(
  $s$detektivja-e-qershive$s$, 'sq', $s$Kush i ha qershitë e gjyshes?$s$,
  $s$Çdo mëngjes, qershitë e pemës së gjyshes janë më pak. Nina vendos të bëhet detektive dhe zbulon një sekret të vogël, me pupla të zeza e me sqep të verdhë.$s$,
  array[
    $s$Në oborrin e gjyshes së Ninës, ishte një pemë e madhe qershie. Në maj, ishte e mbuluar me lule të bardha. Dhe në qershor, degët ishin plot me qershi të kuqe, të ëmbla e të shndritshme, si rruaza. Gjyshja i mblidhte për të bërë reçel, dhe Nina i hante drejt e nga pema, duke i varur në vesh si vathë.$s$,
    $s$Por atë qershor, ndodhi diçka e çuditshme. Çdo mëngjes, kur gjyshja dilte në oborr, qershitë ishin më pak. Në degët e poshtme, qershitë zhdukeshin njëra pas tjetrës. Dhe në tokë, gjyshja gjente bërthama qershie, të pastra e të lëmuara. «Dikush po m'i ha qershitë», tha gjyshja. «Po kush?»$s$,
    $s$Nina u ngrit në këmbë. «Unë do ta zbuloj!» tha. «Do të bëhem detektive.» Gjyshja qeshi. «Mirë, detektive. Ke tri ditë kohë.» Nina mori një fletore të vogël, një laps, një xham zmadhues nga sirtari i gjyshit dhe kapelën e kashtës së gjyshes, që i rrinte shumë e madhe, por që e bënte të dukej si detektive e vërtetë.$s$,
    $s$Dita e parë. Nina filloi me gjurmët. Me xhamin zmadhues, ekzaminoi tokën nën pemë. Gjeti gjurmë të vogla e të rrumbullakëta. «Mace!» shkroi në fletore. Shkoi te maca e fqinjit, një mace e madhe gri, që flinte në diell mbi mur. «A ke ngrënë ti qershitë e gjyshes?» Maca hapi një sy, e shikoi me përbuzje dhe e mbylli përsëri. «Macet s'hanë qershi», tha gjyshja nga dritarja. Nina fshiu shënimin.$s$,
    $s$Ekzaminoi edhe një herë gjurmët. Pranë tyre, kishte edhe gjurmë të tjera, më të vogla, me tre gishta përpara dhe një prapa. «Zogj!» shkroi Nina. «Por çfarë zogu?» Kishte shumë zogj në oborrin e gjyshes: harabela, pëllumba, një qukapik që trokiste në pemën e arrës. Duhej të zbulonte cilin.$s$,
    $s$Dita e dytë. Nina vendosi të ngrihej herët, shumë herët, para se të dilte dielli, dhe të fshihej pas shkurres së trëndafilave, për të parë kush vinte. Vuri orën në pesë. Kur ra zilja, u ngrit e përgjumur, veshi pallton mbi pizhama dhe doli në heshtje në oborr. Ishte ende gjysmë errësirë, dhe bari ishte i lagur nga vesa.$s$,
    $s$Nina u fsheh pas trëndafilave dhe priti. Priti dhe priti. Dëgjoi një qen që lehte larg. Dëgjoi një gjel që këndonte. Dhe pastaj, ndërsa qielli bëhej rozë, dëgjoi një zë të bukur. Ishte një këngë zogu, e gjatë, e ëmbël, si një fyell, që vinte nga pema e qershisë. Nina ngriti kokën ngadalë.$s$,
    $s$Në një degë të poshtme, ishte një zog i zi, krejt i zi, me një sqep të verdhë si portokalli e me një rreth të verdhë rreth syrit. Po këndonte. Dhe pastaj, kur mbaroi këngën, këputi me sqep një qershi të kuqe dhe fluturoi me të. Nina e ndoqi me sy. Zogu fluturoi deri te gardhi i dendur me dredhkë, në fund të oborrit, dhe u zhduk mes gjetheve.$s$,
    $s$Nina shkroi në fletore: «Zogu i zi me sqep të verdhë. Këndon bukur. Merr qershi dhe i çon te gardhi.» Pastaj priti, dhe zogu u kthye. Këputi një qershi tjetër. Fluturoi përsëri te gardhi. Pastaj erdhi një zog tjetër, kafe, pak më i vogël, që bëri të njëjtën gjë. «Janë dy!» shkroi Nina. «Por pse i çojnë qershitë te gardhi?»$s$,
    $s$Dita e tretë. Nina shkoi me gjyshen te gardhi me dredhkë. Me shumë kujdes, me shumë qetësi, gjyshja hapi pak gjethet me dorë. Dhe aty, mes degëve të dendura, ishte një fole. Një fole e bukur, e rrumbullakët, e bërë me bar e me baltë. Dhe brenda folesë, me sqepat e hapur e me pupla të ngatërruara, ishin katër zogj të vegjël, që cicëronin: cip-cip-cip!$s$,
    $s$«Mëllenja», pëshpëriti gjyshja. «Zogu i zi me sqep të verdhë është babai mëllenjë, dhe zogu kafe është nëna. Kanë katër të vegjël, dhe po i ushqejnë me qershitë e mia.» Nina e mbylli gardhin ngadalë, që të mos i trembte. «Pra kjo është zgjidhja e misterit», tha. «Hajdutët e qershive janë një familje mëllenjash!»$s$,
    $s$Nina u mërzit pak. «Gjyshe, po qershitë e tua? Po reçeli?» Gjyshja buzëqeshi dhe i vuri dorën në sup. «Pema ka shumë qershi», tha. «Në degët e larta ka edhe më shumë. Do të kemi mjaft për reçel, dhe edhe për mëllenjat. Dhe në këmbim, do të kemi diçka që reçeli s'mund ta japë: këngën më të bukur të oborrit, çdo mëngjes.»$s$,
    $s$Gjatë javëve që erdhën, Nina i shikonte mëllenjat çdo ditë nga dritarja. I pa të vegjlit të rriteshin, t'u dilnin pupla, të provonin krahët. Dhe një mëngjes, i pa të katër të fluturonin, të ngathët e të gëzuar, deri te pema e qershisë, ku hëngrën qershitë e tyre të para vetë. Dhe babai mëllenjë këndoi më bukur se kurrë.$s$,
    $s$Nina e mbylli fletoren e saj të detektives. Në faqen e fundit, shkroi: «Misteri u zgjidh. Hajdutët: familja Mëllenja, me katër të vegjël. Dënimi: të këndojnë çdo mëngjes për gjyshen. Çështja e mbyllur.» Dhe atë dimër, kur hëngrën reçelin e qershisë me bukë të ngrohtë, gjyshja i tha: «Ky është reçeli më i mirë që kam bërë. E di pse? Sepse e kemi ndarë.»$s$
  ]::text[],
  array['adventure', 'nature']::text[], 36, 84, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gdetektivjaeqershive" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gdetektivjaeqershive)"/><circle cx="32.7" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 91.2Q40 71.6 80 83.6T160 81.9V120H0Z" fill="#A6CDB4"/><path d="M0 103.5Q40 94.7 80 102.7T160 100.2V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M22 44Q28 20 40 8M44 44Q42 24 40 8" fill="none" stroke="#7DA86B" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="48" cy="12" rx="10" ry="5" fill="#7DA86B" transform="rotate(-20 48 12)"/><circle cx="22" cy="48" r="9" fill="#D9644A"/><circle cx="44" cy="48" r="9" fill="#D9644A"/><circle cx="19" cy="45" r="2.4" fill="#FFFFFF" opacity="0.4"/><circle cx="41" cy="45" r="2.4" fill="#FFFFFF" opacity="0.4"/></g></svg>$s$,
  'published', false, 1200, 'editor'
),
(
  $s$bora-e-pare-ne-theth$s$, 'sq', $s$Bora e parë në Theth$s$,
  $s$Në fshatin malor të Thethit bie bora e parë e dimrit. Dy vëllezër kalojnë ditën më të bardhë të vitit dhe mbrëmjen pranë zjarrit të gjyshes.$s$,
  array[
    $s$Thethi është një fshat i vogël lart në Alpet shqiptare, në një luginë të rrethuar nga male aq të larta, sa dielli vonon të dalë në mëngjes dhe ikën herët në mbrëmje. Shtëpitë janë prej guri, me çati të pjerrëta prej dërrase, dhe në mes të luginës rrjedh një lumë i ftohtë e i kaltër.$s$,
    $s$Në një nga ato shtëpi jetonin Gjoni dhe motra e tij e vogël, Lena, bashkë me prindërit dhe gjyshen. Gjithë vjeshtën kishin pritur një gjë: borën e parë. Çdo mëngjes, Lena vraponte te dritarja dhe pyeste: «Ra?» Dhe çdo mëngjes Gjoni tundte kokën: «Jo ende.»$s$,
    $s$Një natë nëntori, Gjoni u zgjua nga një heshtje e çuditshme. Nuk dëgjohej lumi. Nuk dëgjohej era. Nuk dëgjohej asgjë, sikur dikush i kishte vënë botës një jastëk të madh mbi veshë. U ngrit ngadalë dhe shkoi te dritarja. Dhe pa: gjithçka ishte e bardhë. Bora po binte me flokë të mëdha e të ngadalta, si pupla që zbrisnin nga qielli.$s$,
    $s$«Lena!» pëshpëriti, duke e tundur motrën. «Lena, zgjohu! Ra!» Lena hapi sytë, u ngrit me vrap dhe ngjiti hundën pas xhamit. Dhe të dy qëndruan aty, pa folur, duke parë borën që mbulonte oborrin, gardhin, kokat e pemëve dhe malet, deri sa mamaja i gjeti të dy në dritare dhe i ktheu në shtrat. «Bora do të jetë edhe nesër», u tha duke qeshur.$s$,
    $s$Në mëngjes, bota ishte e re. Bora arrinte deri te gjunjët e Gjonit dhe deri te beli i Lenës. Veshën çizmet, pallto të trasha, kapele leshi të thurura nga gjyshja dhe doreza me ngjyra. Kur dolën nga dera, bora kërciste nën këmbë, krrrk, krrrk, si buka e ngrohtë kur e thyen.$s$,
    $s$Bënë një njeri prej bore të madh, me sy prej qymyri, me hundë prej karote dhe me shallin e vjetër të gjyshit. Lena këmbënguli që t'i bënin edhe një qen prej bore, që të mos rrinte vetëm. Pastaj u shtrinë në borë dhe tundën krahët e këmbët, që të bënin engjëj. Bora e ftohtë u hynte në jakë dhe ata qeshnin e bërtisnin.$s$,
    $s$Babai nxori nga hambari sajën e vjetër të drunjtë, atë që e kishte përdorur kur ishte i vogël. U ngjitën në kodrinën pas kishës dhe zbritën me shpejtësi, të dy bashkë, me Gjonin përpara e me Lenën që e mbante fort pas belit. Herën e tretë u përmbysën në një grumbull bore dhe dolën të bardhë nga koka te këmbët, si dy fantazma që qeshnin.$s$,
    $s$Pasdite, babai i çoi deri te ujëvara e Grunasit, që ishte ngrirë pjesërisht. Uji ende rridhte në mes, por anash ishte bërë kristal, me hell akulli të gjatë si qirinj të bardhë që vareshin nga shkëmbi. Dielli i pakët i dimrit i ndriçonte, dhe ata shkëlqenin me ngjyrat e ylberit. «Duket si një pallat mbretëreshe», tha Lena me zë të ulët.$s$,
    $s$Kur dielli u fsheh pas malit, ajri u bë i ftohtë dhe hundët iu skuqën. U kthyen në shtëpi, me çizmet plot borë e me faqet që digjnin. Mamaja u hoqi rrobat e lagura dhe i veshi me pizhame të ngrohta, që i kishte vënë pranë sobës.$s$,
    $s$Gjyshja ishte ulur pranë oxhakut, ku digjej një zjarr i madh me dru ahu. Në një tavë mbi prush po piqeshin gështenja, që kërcisnin e çaheshin. Gjoni dhe Lena u ulën në qilim, pranë këmbëve të gjyshes, me nga një filxhan çaj mali me mjaltë në duar.$s$,
    $s$«Gjyshe», tha Lena, «na trego për dimrat e vjetër.» Gjyshja qeshi. «Kur isha e vogël», tha, «bora binte aq shumë sa s'shihej dera. Babai im hapte një tunel nga shtëpia te hambari, dhe ne vraponim nëpër të si urithë. Dhe gjithë dimrin, nuk vinte asnjë njeri në fshat dhe nuk ikte asnjë. Ishim vetëm ne, mali dhe bora.»$s$,
    $s$«A s'mërziteshit?» pyeti Gjoni. «Kurrë», tha gjyshja. «Kishim zjarrin, gështenjat dhe njëri-tjetrin. Dhe çdo mbrëmje, tregonim përralla. Ashtu si tani.» Dhe ajo filloi t'u tregonte për Zanat e malit, që thuhej se kërcenin mbi borë në netët me hënë.$s$,
    $s$Lena e dëgjonte me kokën mbi gjurin e gjyshes, dhe ngadalë sytë filluan t'i rëndoheshin. Zjarri kërciste, gështenjat mbaruan, dhe jashtë bora vazhdonte të binte, e qetë dhe e heshtur, mbi shtëpitë prej guri, mbi lumin e kaltër e mbi malet e larta. Gjoni u përpoq të rrinte zgjuar deri në fund të përrallës, por nuk ia doli.$s$,
    $s$Babai i mori të dy në krahë dhe i çoi në shtrat. I mbuloi me jorganin e trashë, dhe para se të fikte dritën, hapi pak perden. Jashtë, nën dritën e hënës, njeriu prej bore dhe qeni i tij qëndronin të bardhë e të qetë, si roje mbi oborrin e fjetur. Natën e mirë, Theth. Natën e mirë, borë.$s$
  ]::text[],
  array['sleep', 'nature']::text[], 0, 84, 10, 'house',
