rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M-4 52Q10 30 24 52Q10 56 -4 52Z" fill="#E7B04B"/><path d="M4 46L16 46" fill="none" stroke="#8A5A44" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><path d="M18 40Q32 18 46 40Q32 44 18 40Z" fill="#E7B04B"/><path d="M26 34L38 34" fill="none" stroke="#8A5A44" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><path d="M40 52Q54 30 68 52Q54 56 40 52Z" fill="#E7B04B"/><path d="M48 46L60 46" fill="none" stroke="#8A5A44" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><circle cx="8" cy="10" r="1.4" fill="#FFFFFF"/><circle cx="20" cy="15" r="1.4" fill="#FFFFFF"/><circle cx="44" cy="20" r="1.4" fill="#FFFFFF"/><circle cx="56" cy="25" r="1.4" fill="#FFFFFF"/><circle cx="30" cy="30" r="1.4" fill="#FFFFFF"/></g></svg>$s$,
